mapper.select:
SELECT A.BILL_ID AS billId , A.PROJ_ID AS projId , A.BILL_TITLE AS billTitle , A.BILL_AMT AS billAmt , A.TAX_BILL_DT AS taxBillDt , A.IS_PAID AS isPaid , B.PROJ_NM AS projNm FROM TB_BILLING A LEFT JOIN TB_PROJECT B ON A.PROJ_ID = B.PROJ_ID WHERE A.DEL_YN = 'N'
AND A.BILL_TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.BILL_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_BILLING (
    PROJ_ID, BILL_TITLE, BILL_AMT, TAX_BILL_DT, PAY_DT, IS_PAID, ACTUAL_PAY_DT, BILL_REMARK
) VALUES (
    #{projId}, #{billTitle}, #{billAmt}, NULLIF(#{taxBillDt},''), NULLIF(#{payDt},''), #{isPaid}, NULLIF(#{actualPayDt},''), #{billRemark}
)

mapper.update:
UPDATE TB_BILLING
SET
      PROJ_ID = #{projId}
    , BILL_TITLE = #{billTitle}
    , BILL_AMT = #{billAmt}
    , TAX_BILL_DT = NULLIF(#{taxBillDt}, '')
    , PAY_DT = NULLIF(#{payDt}, '')
    , IS_PAID = #{isPaid}
    , ACTUAL_PAY_DT = NULLIF(#{actualPayDt}, '')
    , BILL_REMARK = #{billRemark}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , LAST_UPDT_PNTTM = NOW()
WHERE BILL_ID = #{billId}

UPDATE TB_BILLING
SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
    , LAST_UPDT_PNTTM = NOW()
WHERE BILL_ID = #{billId}
